$events=$pdo->query("SELECT id,name,event_code,default_vote_price FROM events ORDER BY name")->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){
 $eventId=(int)($_POST['event_id']??0); $name=trim($_POST['name']??''); $desc=trim($_POST['description']??''); $price=(float)($_POST['vote_price']??1); $max=max(1,(int)($_POST['max_votes_per_transaction']??20)); $phoneLimit=trim($_POST['max_votes_per_phone']??''); $status=$_POST['status']??'Active'; $order=max(0,(int)($_POST['display_order']??0));
 if(!$eventId||$name===''){flash('danger','Event and category name are required.');} else {try{$s=$pdo->prepare('SELECT default_vote_price FROM events WHERE id=?');$s->execute([$eventId]);$event=$s->fetch();if(!$event)throw new RuntimeException('Selected event not found.');if($price<=0)$price=(float)$event['default_vote_price'];$code=generateCategoryCode($pdo,$eventId,$name);$q=$pdo->prepare('INSERT INTO categories(event_id,name,category_code,description,vote_price,max_votes_per_transaction,max_votes_per_phone,display_order,status) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([$eventId,$name,$code,$desc,$price,$max,$phoneLimit===''?null:(int)$phoneLimit,$order,$status]);flash('success',"Category created with code {$code}.");redirect('index.php?event_id='.$eventId);}catch(Throwable $e){flash('danger',$e->getMessage());}}}
