<main class="main"><?php require __DIR__.'/../../includes/topbar.php';?><section class="content"><?php showFlash();?><div class="d-flex justify-content-between align-items-end mb-4"><div><span class="section-kicker">EVENT MANAGEMENT</span><h1 class="page-title">Create Category</h1><p class="page-subtitle">Categories are isolated within their parent event.</p></div><a href="index.php" class="btn btn-light border">Back</a></div><div class="panel"><div class="panel-body"><form method="post" class="row g-3"><div class="col-md-8"><label class="form-label">Event *</label><select name="event_id" id="event" class="form-select" required><option value="">Select event</option><?php foreach($events as $e):?><option value="<?=$e['id']?>"><?=e($e['name'])?> — <?=e($e['event_code'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Status</label><select name="status" class="form-select"><option>Active</option><option>Inactive</option></select></div><div class="col-md-8"><label class="form-label">Category Name *</label><input name="name" id="name" class="form-control" required placeholder="Most Famous Student"></div><div class="col-md-4"><label class="form-label">Display Order</label><input type="number" min="0" name="display_order" value="0" class="form-control"></div><div class="col-md-4"><label class="form-label">Vote Price (GHS)</label><input type="number" min="0.01" step="0.01" name="vote_price" value="1.00" class="form-control"></div><div class="col-md-4"><label class="form-label">Max Votes / Transaction</label><input type="number" min="1" name="max_votes_per_transaction" value="20" class="form-control"></div><div class="col-md-4"><label class="form-label">Max Votes / Phone <span class="text-muted">(optional)</span></label><input type="number" min="1" name="max_votes_per_phone" class="form-control"></div><div class="col-12"><label class="form-label">Description</label><textarea name="description" class="form-control" rows="4"></textar